// Validate metadata for distribution readiness
const metadata = $input.first().json.metadata;

const validation = {
  // Required fields for DSPs
  required_fields: {
    title: !!metadata.title,
    artist: !!metadata.artist,
    album: !!metadata.album,
    release_year: !!metadata.releaseYear,
    genre: !!metadata.genre,
    isrc: !!metadata.isrc
  },

  // Professional fields
  professional_fields: {
    record_label: !!metadata.recordLabel,
    producer: !!metadata.producer,
    copyright_holder: !!metadata.copyrightHolder,
    explicit: metadata.explicit !== undefined,
    language: !!metadata.language
  },

  // Technical requirements
  technical_requirements: {
    duration: metadata.duration > 30, // Minimum 30 seconds
    cover_art: !!metadata.cover_image_url,
    audio_quality: metadata.bitrate >= 128, // Minimum 128kbps
    format_supported: ['mp3', 'wav', 'm4a'].includes(metadata.format)
  }
};

// Calculate readiness score
const allChecks = {
  ...validation.required_fields,
  ...validation.professional_fields,
  ...validation.technical_requirements
};

const passedChecks = Object.values(allChecks).filter(Boolean).length;
const totalChecks = Object.keys(allChecks).length;
const readinessScore = Math.round((passedChecks / totalChecks) * 100);

// Determine distribution readiness
const distributionReady = readinessScore >= 80;
const requiredFieldsComplete = Object.values(validation.required_fields).every(Boolean);

return {
  ...metadata,
  validation,
  readiness_score: readinessScore,
  distribution_ready: distributionReady,
  required_fields_complete: requiredFieldsComplete,
  missing_fields: Object.entries(allChecks)
    .filter(([key, value]) => !value)
    .map(([key]) => key)
};

// Generate distribution package
const metadata = $input.first().json;

// Create DSP-ready metadata
const dspMetadata = {
  // Spotify/Apple Music format
  spotify: {
    track_title: metadata.title,
    artist_name: metadata.artist,
    album_title: metadata.album,
    release_date: `${metadata.releaseYear}-01-01`,
    genre: metadata.genre,
    isrc: metadata.isrc,
    explicit: metadata.explicit || false,
    language: metadata.language || 'en',
    copyright: metadata.copyright_holder || metadata.artist,
    producer: metadata.producer,
    label: metadata.recordLabel || 'Independent'
  },

  // YouTube Music format
  youtube: {
    title: metadata.title,
    artist: metadata.artist,
    album: metadata.album,
    year: metadata.releaseYear,
    genre: metadata.genre,
    isrc: metadata.isrc,
    content_rating: metadata.explicit ? 'explicit' : 'clean'
  },

  // SoundCloud format
  soundcloud: {
    title: `${metadata.artist} - ${metadata.title}`,
    description: metadata.description || `${metadata.title} by ${metadata.artist}`,
    genre: metadata.genre,
    tags: metadata.tags || [metadata.genre, metadata.artist],
    release_date: `${metadata.releaseYear}-01-01`
  }
};

// Generate delivery package
const deliveryPackage = {
  metadata: dspMetadata,
  assets: {
    audio_file: metadata.audio_url,
    cover_art: metadata.cover_image_url,
    waveform: metadata.waveform_url || null
  },
  distribution_info: {
    ready_for_distribution: true,
    platforms: ['spotify', 'apple_music', 'youtube_music', 'soundcloud'],
    estimated_delivery: '24-48 hours',
    generated_at: new Date().toISOString()
  }
};

return deliveryPackage;

// Generate improvement recommendations
const metadata = $input.first().json;
const missingFields = metadata.missing_fields || [];

const recommendations = {
  priority_fixes: [],
  suggestions: [],
  readiness_score: metadata.readiness_score
};

// Priority fixes for required fields
if (missingFields.includes('title')) {
  recommendations.priority_fixes.push('Add track title');
}
if (missingFields.includes('artist')) {
  recommendations.priority_fixes.push('Add artist name');
}
if (missingFields.includes('album')) {
  recommendations.priority_fixes.push('Add album/EP name');
}
if (missingFields.includes('isrc')) {
  recommendations.priority_fixes.push('Generate ISRC code');
}

// Suggestions for professional fields
if (missingFields.includes('cover_art')) {
  recommendations.suggestions.push('Upload high-quality cover art (1400x1400px)');
}
if (missingFields.includes('producer')) {
  recommendations.suggestions.push('Add producer credits');
}
if (missingFields.includes('record_label')) {
  recommendations.suggestions.push('Specify record label or use "Independent"');
}

// Technical suggestions
if (missingFields.includes('audio_quality')) {
  recommendations.suggestions.push('Ensure audio quality is at least 128kbps');
}
if (missingFields.includes('duration')) {
  recommendations.suggestions.push('Track must be at least 30 seconds long');
}

return {
  ...metadata,
  recommendations,
  next_steps: recommendations.priority_fixes.length > 0 
    ? 'Complete priority fixes to enable distribution'
    : 'Ready for distribution - consider suggestions for better placement'
};
